from pathlib import Path
import base64,csv,html,json,hashlib
import markdown
R=Path(__file__).resolve().parents[2]; run=R/'analysis/runs/candidate_20261108_v2'; notes=R/'근감소증과 인체계측 - 분석 길잡이'; dest=R/'최종분석보고서.html'
mdfiles=[notes/'01-concept 연구와 변수.md',notes/'01-paper 연구와 변수.md',notes/'02-concept 로지스틱 회귀와 표본설계.md',notes/'02-paper 회귀 결과.md',notes/'03-concept ROC와 검증.md',notes/'03-paper ROC 결과와 한계.md']
def md(p): return markdown.markdown(p.read_text(encoding='utf-8-sig'),extensions=['tables','fenced_code'])
def img(n): return 'data:image/png;base64,'+base64.b64encode((run/n).read_bytes()).decode()
def table(fname,cols):
    with (run/fname).open(encoding='utf-8-sig',newline='') as f: rows=list(csv.DictReader(f))
    tr=[]
    for row in rows:
        cells=[]
        for c in cols:
            s=row.get(c,'')
            try:
                v=float(s)
                if c=='p': s=f'{v:.2g}'
                elif c not in ['n','events','model','train_n','test_n','design_df']: s=f'{v:.3f}'
            except ValueError: pass
            cells.append('<td>'+html.escape(s)+'</td>')
        tr.append('<tr>'+''.join(cells)+'</tr>')
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+html.escape(c)+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join(tr)+'</tbody></table></div>'
def download(fname,label):
    data=base64.b64encode((run/fname).read_bytes()).decode()
    return f'<a class="download" download="{html.escape(fname)}" href="data:text/csv;base64,{data}">{label} CSV 내려받기</a>'
chapters=''
for i in range(3):
    chapters+=f'<section class="chapter" id="step{i+1}"><div class="section-label">단계 0{i+1}</div><div class="pair"><article class="panel concept"><div class="tag">CONCEPT · 일반 개념</div>{md(mdfiles[2*i])}</article><article class="panel paper"><div class="tag">PAPER · 논문과 자료</div>{md(mdfiles[2*i+1])}</article></div></section>'
orcols=['outcome','index','increment','model','n','events','OR','CI_low','CI_high','p','design_df','paper_OR']
roc=['outcome','index','train_n','test_n','train_auc','paper_auc','cutoff','train_youden','train_sensitivity','train_specificity','test_auc','test_sensitivity','test_specificity']
paper=md(R/'논문 근거.md')
raw=''.join(f'<details><summary>{html.escape(p.name)}</summary><pre>{html.escape(p.read_text(encoding="utf-8-sig"))}</pre></details>' for p in mdfiles)
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f3f6f8;color:#162939;font-family:Malgun Gothic,Segoe UI,sans-serif;line-height:1.72}a{color:#086e80}header{background:#102f40;color:white;padding:52px max(5vw,24px) 46px}header .eyebrow{color:#96e1dc;font-size:.8rem;font-weight:800;letter-spacing:.12em}h1{font-size:clamp(1.7rem,4vw,3rem);line-height:1.3;margin:.35em 0}header p{max-width:850px;color:#d2e5e9}main{max-width:1260px;margin:auto;padding:28px 24px 80px}.bar{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0 28px}.bar a,.download{display:inline-block;background:white;border:1px solid #cbdde0;border-radius:8px;padding:8px 12px;font-size:.87rem;text-decoration:none}.alert{background:#fff5e0;border-left:5px solid #d49926;padding:18px 22px;border-radius:8px;margin:24px 0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric{background:white;border:1px solid #dce7e9;border-radius:12px;padding:18px}.metric strong{font-size:1.7rem;color:#0b6c77;display:block}.metric small{color:#536c77}.chapter,.block{margin-top:36px}.section-label{color:#147a80;font-size:.78rem;letter-spacing:.12em;font-weight:800}.pair{display:grid;grid-template-columns:1fr 1fr;gap:14px}.panel,.blockbox{background:white;border:1px solid #dce7e9;border-radius:12px;padding:24px;min-width:0}.panel h1{font-size:1.3rem;color:#163d49}.tag{font-size:.73rem;font-weight:800;letter-spacing:.08em;color:#15747b}.paper .tag{color:#8e6417}h2{font-size:1.5rem;line-height:1.3}h3{font-size:1.1rem}table{border-collapse:collapse;width:100%;font-size:.78rem;white-space:nowrap}th,td{padding:9px 11px;border-bottom:1px solid #e2eaeb;text-align:left}th{background:#eaf3f3;color:#20454d;position:sticky;top:0}.table-wrap{overflow:auto;max-height:640px;border:1px solid #dce7e9;border-radius:8px}figure{margin:0}figure img{display:block;width:100%;height:auto}.charts{display:grid;grid-template-columns:1fr 1fr;gap:12px}figcaption{font-size:.82rem;color:#48616b}details{margin:10px 0;border:1px solid #dce7e9;border-radius:8px;padding:10px 14px}summary{cursor:pointer;font-weight:700}pre{white-space:pre-wrap;word-break:break-word;background:#f4f7f8;padding:12px;font-size:.8rem}code{word-break:break-word}.muted{color:#526873;font-size:.9rem}.footer{margin-top:40px;color:#57707a;font-size:.85rem} @media(max-width:760px){.cards{grid-template-columns:repeat(2,1fr)}.pair,.charts{grid-template-columns:1fr}main{padding:18px 14px 50px}.panel,.blockbox{padding:17px}header{padding:34px 18px}}@media print{body{background:white}.bar,.download{display:none}.panel,.blockbox,.metric{break-inside:avoid}.table-wrap{max-height:none;overflow:visible}table{font-size:7px}.pair{display:block}}'''
htmlout=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>7주차 | 로지스틱 회귀와 진단 성능</title><style>{css}</style></head><body><header><div class="eyebrow">BIOMEDICAL PROGRAMMING · WEEK 07</div><h1>인체계측 지표와 근감소증<br>로지스틱 회귀와 진단 성능</h1><p>NHANES 2011–2018 · 논문 이해부터 가중 회귀와 ROC 검토까지 · 실행 candidate_20261108_v2</p></header><main><nav class="bar" aria-label="목차"><a href="#status">분석 상태</a><a href="#step1">연구와 자료</a><a href="#step2">회귀</a><a href="#step3">ROC</a><a href="#results">결과 전체</a><a href="#paper">원문 근거</a><a href="#limits">한계와 기록</a></nav><div class="alert" id="status"><strong>정확 재현 미완료 · 공개 자료의 후보 분석</strong><br>저자의 선정·질환 정의·가중치·예측모형이 충분히 식별되지 않아, 아래 결과는 논문 수치와 단순 대조한 분석자 후보입니다. 연관과 동시점 구분 능력이며 인과효과나 미래 발병 예측으로 단정할 수 없습니다.</div><div class="cards"><div class="metric"><small>논문 최종 대상자</small><strong>8,159명</strong></div><div class="metric"><small>후보 완전사례</small><strong>8,086명</strong></div><div class="metric"><small>SA / SO 후보 사건</small><strong>687 / 479</strong></div><div class="metric"><small>훈련 / 내부 검증</small><strong>6,468 / 1,618</strong></div></div>{chapters}<section class="block" id="figures"><div class="section-label">VISUAL EVIDENCE</div><h2>지표별 ROC 곡선</h2><p class="muted">후보 집단의 직접 지표, 식이가중치, 학습 집합. 논문의 단계적 회귀 예측모형 곡선과 같다고 가정하지 않습니다.</p><div class="charts"><figure class="blockbox"><img src="{img('ROC_SA.png')}" alt="SA 후보 학습 집합 지표별 가중 ROC"><figcaption>SA · 학습 자료 · 내부 검증 결과는 아래 표</figcaption></figure><figure class="blockbox"><img src="{img('ROC_SO.png')}" alt="SO 후보 학습 집합 지표별 가중 ROC"><figcaption>SO · 학습 자료 · 내부 검증 결과는 아래 표</figcaption></figure></div></section><section class="block" id="results"><div class="section-label">FULL RESULTS</div><h2>회귀 결과와 원문 비교</h2><div class="blockbox"><p>전체 30개 모형. OR과 CI는 동일한 완전사례와 두 날 식이가중치를 사용한 후보치입니다. <b>paper_OR은 원문 수치이며 표본·단위·모형의 동등성이 확인되지 않았습니다.</b> ABSI 0.01, WHtR 0.1, BRI 1, BMI 1 kg/m², LBSIZ 1 SD 증가당 OR입니다.</p>{download('table3_comparison.csv','회귀 대조 전체')}{table('table3_comparison.csv',orcols)}</div><h2>ROC와 컷오프 비교</h2><div class="blockbox"><p>컷오프는 학습 자료의 Youden 최댓값이며 검증에 고정했습니다. 논문 Table 4에는 컷오프가 없습니다. 원문 AUC와 단순 지표 AUC는 직접 비교 가능한 동일 모형으로 확인되지 않았습니다.</p>{download('table4_comparison.csv','ROC 대조 전체')}{table('table4_comparison.csv',roc)}</div></section><section class="block" id="paper"><div class="section-label">PUBLISHED EVIDENCE</div><h2>논문 근거와 원문 보고값</h2><div class="blockbox">{paper}</div></section><section class="block" id="limits"><div class="section-label">QUALITY & LIMITATIONS</div><h2>검토 범위와 남은 일</h2><div class="blockbox"><ul><li>논문의 정확한 제외 규칙, 근육량 DXA 열 구성, 건강 공변량 코딩, 가중치와 OR 단위는 불명확합니다. 자가보고 질병은 대체 변수입니다.</li><li>SA/SO에 BMI가 들어가므로 BMI 지표의 성능은 정의상 공유되는 정보를 반영할 수 있습니다. LBSIZ 표준화를 분할 전에 시행한 컷오프는 정보 누출 가능성이 있습니다.</li><li>초기 실행 candidate_20261108의 회귀 30개는 인덱싱 오류로 실패했습니다. v2에서 수정 후 새 실행했으며, 결과 30개 상태와 CI·p값 내부 일관성을 독립 검토했습니다. 독립 survey 패키지 수치 대조는 아직 하지 않았습니다.</li><li>논문의 단계적 예측모형 재현, ROC 신뢰구간 및 2001–2004 BIA 별도 검증은 미완료입니다. 원자료 전체 8,086명의 개별 분석 데이터는 이 보고서에 내장되지 않았습니다. 재생성할 원자료·코드·해시는 로컬 analysis 폴더에 있습니다.</li></ul><p>원문: Wu et al. Scientific Reports 14:31776 (2024), DOI <a href="https://doi.org/10.1038/s41598-024-82751-7">10.1038/s41598-024-82751-7</a>. CDC <a href="https://wwwn.cdc.gov/nchs/nhanes/tutorials/weighting.aspx">NHANES 가중치 안내</a>. 내부 검토는 외부 표본 검증이 아닙니다.</p><details><summary>학습 문서 원문 보기</summary>{raw}</details></div></section><p class="footer">원문과 분석자 후보를 구분해 읽으세요 · 생성본은 CSV와 그림을 내장하며 인터넷 없이 열 수 있습니다.</p></main></body></html>'''
dest.write_text(htmlout,encoding='utf-8'); print(dest, dest.stat().st_size, hashlib.sha256(dest.read_bytes()).hexdigest())
